221: type EventHandler = (...args: any[]) => void;
222: const processListeners = new Map<string, EventHandler[]>();
223: const dispatchers = {
224:   exit: (...args: any[]) => {
225:     processListeners.get('exit')?.forEach(handler => {
226:       return handler(...args);
227:     });
228:   },
229:   SIGINT: (...args: any[]) => {
230:     processListeners.get('SIGINT')?.forEach(handler => {
231:       return handler(...args);
232:     });
233:   },
234:   SIGHUP: (...args: any[]) => {
235:     processListeners.get('SIGHUP')?.forEach(handler => {
236:       return handler(...args);
237:     });
238:   },
239:   SIGTERM: (...args: any[]) => {
240:     processListeners.get('SIGTERM')?.forEach(handler => {
241:       return handler(...args);
242:     });
243:   },
244: };
245: 
246: function subscribeToProcessEvent(
247:   event: 'exit' | 'SIGINT' | 'SIGHUP' | 'SIGTERM',
248:   handler: EventHandler,
249: ): void {
250:   const listeners = processListeners.get(event) || [];
251:   if (listeners.length === 0) {
252:     process.on(event, dispatchers[event]);
253:   }
254:   listeners.push(handler);
255:   processListeners.set(event, listeners);
256: }
257: 
258: function unsubscribeFromProcessEvent(
259:   event: 'exit' | 'SIGINT' | 'SIGHUP' | 'SIGTERM',
260:   handler: EventHandler,
261: ): void {
262:   const listeners = processListeners.get(event) || [];
263:   const existingListenerIdx = listeners.indexOf(handler);
264:   if (existingListenerIdx === -1) {
265:     return;
266:   }
267:   listeners.splice(existingListenerIdx, 1);
268:   processListeners.set(event, listeners);
269:   if (listeners.length === 0) {
270:     process.off(event, dispatchers[event]);
271:   }
272: }
