24: export async function unpackArchive(
25:   archivePath: string,
26:   folderPath: string,
27: ): Promise<void> {
28:   if (!path.isAbsolute(folderPath)) {
29:     folderPath = path.resolve(process.cwd(), folderPath);
30:   }
31:   if (archivePath.endsWith('.zip')) {
32:     await mkdir(folderPath, {recursive: true});
33:     await extractZip(archivePath, folderPath);
34:   } else if (archivePath.endsWith('.tar.bz2')) {
35:     await extractTar(archivePath, folderPath, 'bzip2');
36:   } else if (archivePath.endsWith('.dmg')) {
37:     await mkdir(folderPath);
38:     await installDMG(archivePath, folderPath);
39:   } else if (archivePath.endsWith('.exe')) {
40:     // Firefox on Windows.
41:     const result = spawnSync(archivePath, [`/ExtractDir=${folderPath}`], {
42:       env: {
43:         __compat_layer: 'RunAsInvoker',
44:       },
45:     });
46:     if (result.status !== 0) {
47:       throw new Error(
48:         `Failed to extract ${archivePath} to ${folderPath}: ${result.output}`,
49:       );
50:     }
51:   } else if (archivePath.endsWith('.tar.xz')) {
52:     await extractTar(archivePath, folderPath, 'xz');
53:   } else {
54:     throw new Error(`Unsupported archive format: ${archivePath}`);
55:   }
56: }
