58: function createTransformStream(
59:   child: ChildProcessByStdio<Writable, Readable, null>,
60: ): Transform {
61:   const stream = new Stream.Transform({
62:     transform(chunk, encoding, callback) {
63:       if (!child.stdin.write(chunk, encoding)) {
64:         child.stdin.once('drain', callback);
65:       } else {
66:         callback();
67:       }
68:     },
69: 
70:     flush(callback) {
71:       if (child.stdout.destroyed) {
72:         callback();
73:       } else {
74:         child.stdin.end();
75:         child.stdout.on('close', callback);
76:       }
77:     },
78:   });
79: 
80:   child.stdin.on('error', e => {
81:     if ('code' in e && e.code === 'EPIPE') {
82:       // finished before reading the file finished (i.e. head)
83:       stream.emit('end');
84:     } else {
85:       stream.destroy(e);
86:     }
87:   });
88: 
89:   child.stdout
90:     .on('data', data => {
91:       return stream.push(data);
92:     })
93:     .on('error', e => {
94:       return stream.destroy(e);
95:     });
96: 
97:   child.once('close', () => {
98:     return stream.end();
99:   });
100: 
101:   return stream;
102: }
