115: async function extractTar(
116:   tarPath: string,
117:   folderPath: string,
118:   decompressUtilityName: keyof typeof internalConstantsForTesting,
119: ): Promise<void> {
120:   const {unpackTar} = await import('modern-tar/fs');
121:   return await new Promise<void>((fulfill, reject) => {
122:     function handleError(utilityName: string) {
123:       return (error: Error) => {
124:         if ('code' in error && error.code === 'ENOENT') {
125:           error = new Error(
126:             `\`${utilityName}\` utility is required to unpack this archive`,
127:             {
128:               cause: error,
129:             },
130:           );
131:         }
132:         reject(error);
133:       };
134:     }
135:     const unpack = spawn(
136:       internalConstantsForTesting[decompressUtilityName],
137:       ['-d'],
138:       {
139:         stdio: ['pipe', 'pipe', 'inherit'],
140:       },
141:     )
142:       .once('error', handleError(decompressUtilityName))
143:       .once('exit', code => {
144:         debugFileUtil?.(`${decompressUtilityName} exited, code=${code}`);
145:       });
146: 
147:     const tar = unpackTar(folderPath);
148:     tar.once('error', handleError('tar'));
149:     tar.once('finish', fulfill);
150:     createReadStream(tarPath).pipe(createTransformStream(unpack)).pipe(tar);
151:   });
152: }
