154: /**
155:  * @internal
156:  */
157: async function installDMG(dmgPath: string, folderPath: string): Promise<void> {
158:   const {stdout} = await execFileAsync('hdiutil', [
159:     'attach',
160:     '-nobrowse',
161:     '-noautoopen',
162:     dmgPath,
163:   ]);
164: 
165:   const volumes = stdout.match(/\/Volumes\/(.*)/m);
166:   if (!volumes) {
167:     throw new Error(`Could not find volume path in ${stdout}`);
168:   }
169:   const mountPath = volumes[0]!;
170: 
171:   try {
172:     const fileNames = await readdir(mountPath);
173:     const appName = fileNames.find(item => {
174:       return typeof item === 'string' && item.endsWith('.app');
175:     });
176:     if (!appName) {
177:       throw new Error(`Cannot find app in ${mountPath}`);
178:     }
179:     const mountedPath = path.join(mountPath!, appName);
180: 
181:     await execFileAsync('cp', ['-R', mountedPath, folderPath]);
182:   } finally {
183:     await execFileAsync('hdiutil', ['detach', mountPath, '-quiet']);
184:   }
185: }
