187: /**
188:  * @internal
189:  */
190: async function extractZip(
191:   archivePath: string,
192:   folderPath: string,
193: ): Promise<void> {
194:   try {
195:     if (process.platform === 'win32') {
196:       const systemRoot =
197:         process.env['SystemRoot'] ?? process.env['SYSTEMROOT'] ?? 'C:\\Windows';
198:       try {
199:         const systemTar = `${systemRoot}\\System32\\tar.exe`;
200:         // -x: extract files
201:         // -f: specify the archive file
202:         // -C: extract to the specified directory
203:         await execFileAsync(systemTar, ['-xf', archivePath, '-C', folderPath]);
204:         return;
205:       } catch (tarError) {
206:         debugFileUtil?.(`tar.exe extraction failed: ${tarError}`);
207:       }
208:       try {
209:         await execFileAsync('powershell.exe', [
210:           '-NoProfile',
211:           '-NonInteractive',
212:           '-Command',
213:           '& { Expand-Archive -LiteralPath $args[0] -DestinationPath $args[1] -Force }',
214:           archivePath,
215:           folderPath,
216:         ]);
217:         return;
218:       } catch (powershellError) {
219:         debugFileUtil?.(`powershell.exe extraction failed: ${powershellError}`);
220:       }
221:       await execFileAsync('pwsh.exe', [
222:         '-NoProfile',
223:         '-NonInteractive',
224:         '-Command',
225:         '& { Expand-Archive -LiteralPath $args[0] -DestinationPath $args[1] -Force }',
226:         archivePath,
227:         folderPath,
228:       ]);
229:     } else {
230:       // -o: overwrite existing files without prompting
231:       // -d: extract files into the specified directory
232:       await execFileAsync('unzip', ['-o', archivePath, '-d', folderPath]);
233:     }
234:   } catch (error: any) {
235:     if (error?.code === 'ENOENT') {
236:       throw new Error(
237:         `Extraction failed: Required native binary ('tar.exe', 'powershell.exe', 'pwsh.exe' or 'unzip') was not found in the system PATH.`,
238:       );
239:     }
240:     throw new Error(
241:       `Extraction failed: ${error?.stderr?.toString() || error?.message}`,
242:     );
243:   }
244: }

